mapper.select:
select s.ses_id as sessionId, s.ses_candidate_id as candidateId, s.ses_position_id as positionId, s.ses_cascade_round as round, s.ses_mode as mode, s.ses_rec_url as recUrl, e.evl_id as evaluationId, e.evl_overall_score as overallScore, e.evl_recommendation as recommendation, e.evl_hr_status as hrStatus, e.evl_hr_recommendation as hrRecommendation, u.nick_name as candidateName, pos.pos_title as positionTitle from t_int_session s join t_int_evaluation e on e.evl_session_id = s.ses_id left join t_tal t on t.tal_id = s.ses_candidate_id left join sys_user u on u.user_id = t.tal_user_id left join t_pos pos on pos.pos_id = s.ses_position_id
e.evl_hr_status = #{status}
order by e.evl_created_at desc

mapper.update:
update t_tal
set tal_status = #{status}, tal_updated_at = now()
where tal_id = #{talId}
